import React, { useContext, useEffect } from "react";
import { Link } from "react-router-dom";
import styled, { keyframes } from "styled-components";
import PageWrapper from "../components/PageWrapper";
import { ThemeContext } from "../components/ThemeContext";

const fadeInUp = keyframes`
  0% { opacity: 0; transform: translateY(20px);}
  100% { opacity: 1; transform: translateY(0);}
`;

const HomeWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 60px;
  padding: 60px 20px;
  min-height: 100vh;
  transition: background 0.3s, color 0.3s;
`;

const Hero = styled.div`
  background: ${({ darkMode }) =>
    darkMode
      ? "linear-gradient(135deg, #1f1f1f, #2b2b2b)"
      : "linear-gradient(135deg, #fefefe, #f0f0f0)"};
  border-radius: 12px;
  padding: 80px 40px;
  text-align: center;
  box-shadow: ${({ darkMode }) =>
    darkMode
      ? "0 15px 30px rgba(0,0,0,0.6)"
      : "0 15px 30px rgba(0,0,0,0.15)"};
  animation: ${fadeInUp} 0.8s ease forwards;
`;

const HeroTitle = styled.h1`
  font-size: 48px;
  margin-bottom: 20px;
  color: ${({ darkMode }) => (darkMode ? "#e50914" : "#e74c3c")};
`;

const HeroSubtitle = styled.p`
  font-size: 20px;
  margin-bottom: 40px;
  color: ${({ darkMode }) => (darkMode ? "#ccc" : "#555")};
`;

const HeroButton = styled(Link)`
  background-color: #e50914;
  color: #fff;
  padding: 18px 40px;
  font-size: 20px;
  border-radius: 8px;
  text-decoration: none;
  transition: all 0.3s ease;

  &:hover {
    background-color: #ff1a2d;
    transform: translateY(-3px);
  }
`;

const SectionGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 40px;
`;

const Card = styled(Link)`
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  height: 350px;
  border-radius: 12px;
  padding: 20px;
  color: #fff;
  text-decoration: none;
  position: relative;
  overflow: hidden;
  box-shadow: ${({ darkMode }) =>
    darkMode ? "0 10px 25px rgba(0,0,0,0.7)" : "0 10px 25px rgba(0,0,0,0.2)"};
  transition: all 0.3s ease;

  &:hover {
    transform: scale(1.05);
  }

  &:before {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(0deg, rgba(0,0,0,0.5), rgba(0,0,0,0.1));
    z-index: 0;
  }
`;

const CardContent = styled.div`
  position: relative;
  z-index: 1;
`;

const CardTitle = styled.h3`
  font-size: 24px;
  margin-bottom: 10px;
`;

const CardDescription = styled.p`
  font-size: 16px;
`;

const colors = [
  { bg1: "#ff9a9e", bg2: "#fad0c4" },
  { bg1: "#a18cd1", bg2: "#fbc2eb" },
  { bg1: "#fbc2eb", bg2: "#a6c1ee" },
];

const Home = () => {
  const { darkMode } = useContext(ThemeContext);

  useEffect(() => {
    document.body.style.background = darkMode ? "#1e1e1e" : "#f5f5f5";
    document.body.style.color = darkMode ? "#e0e0e0" : "#121212";
  }, [darkMode]);

  return (
    <PageWrapper>
      <HomeWrapper>
        {/* HERO */}
        <Hero darkMode={darkMode}>
          <HeroTitle darkMode={darkMode}>Welcome to My Book Library 📚</HeroTitle>
          <HeroSubtitle darkMode={darkMode}>
            Discover, add, and manage your personal book collection effortlessly.
          </HeroSubtitle>
          <HeroButton to="/books">Explore Books</HeroButton>
        </Hero>

        {/* SECTION CARDS */}
        <SectionGrid>
          <Card
            to="/add"
            darkMode={darkMode}
            style={{
              background: `linear-gradient(135deg, ${colors[0].bg1}, ${colors[0].bg2})`,
            }}
          >
            <CardContent>
              <CardTitle>Add a New Book</CardTitle>
              <CardDescription>Add your personal collection quickly.</CardDescription>
            </CardContent>
          </Card>

          <Card
            to="/mybooks"
            darkMode={darkMode}
            style={{
              background: `linear-gradient(135deg, ${colors[1].bg1}, ${colors[1].bg2})`,
            }}
          >
            <CardContent>
              <CardTitle>My Book Collection</CardTitle>
              <CardDescription>View and manage all your books.</CardDescription>
            </CardContent>
          </Card>

          <Card
            to="/about"
            darkMode={darkMode}
            style={{
              background: `linear-gradient(135deg, ${colors[2].bg1}, ${colors[2].bg2})`,
            }}
          >
            <CardContent>
              <CardTitle>About This App</CardTitle>
              <CardDescription>Learn how to use the library efficiently.</CardDescription>
            </CardContent>
          </Card>
        </SectionGrid>
      </HomeWrapper>
    </PageWrapper>
  );
};

export default Home;
